-- ---------- UNIVERSITES ----------
INSERT INTO universites (slug, nom, description, ville, site_web, annee_creation, statut, contact_email, contact_telephone, stats_etudiants, stats_ecoles, stats_campuses, histoire, presentation, admission_info)
VALUES ('uac', 'Université d''Abomey-Calavi', 'L''UAC, tout le monde en parle : c''est la plus grande université du Bénin, et de loin. Elle regroupe 27 écoles et facultés, de la médecine au droit en passant par l''agronomie, les langues ou l''informatique. Si tu cherches une filière, il y a de très fortes chances qu''elle existe ici.', 'Abomey-Calavi', NULL, 1970, 'Publique', NULL, NULL, NULL, '27', 'Abomey-Calavi, Cotonou, Porto-Novo, Adjarra', 'Tout commence en 1970, sous le nom d''Université Nationale du Bénin (UNB) : c''est la toute première université du pays. En 2001, elle prend le nom qu''on lui connaît aujourd''hui, Université d''Abomey-Calavi, en même temps que le paysage universitaire béninois s''ouvre à d''autres établissements publics. Depuis plus de 50 ans, c''est elle qui a formé le plus gros des cadres, médecins, ingénieurs, enseignants et chercheurs du Bénin.', 'À l''UAC, tu as le choix entre des facultés « classiques » (droit, lettres, sciences économiques, sciences humaines...) et des écoles professionnelles plus spécialisées (École Polytechnique d''Abomey-Calavi pour l''ingénierie, ENEAM pour la gestion et l''économie, ENA pour l''administration, IFRI pour l''informatique, IMSP pour les maths et la physique, Faculté des Sciences de la Santé pour la médecine...). Certaines écoles sont même délocalisées, comme la FLASH d''Adjarra. Bref, une vraie mosaïque de formations sous un même toit.', 'Deux portes d''entrée : le classement national du bac (pour la plupart des filières classiques) ou le concours (pour les filières plus sélectives comme les sciences de la santé, le journalisme ou les métiers du sport). Selon la filière et ton rang, tu peux décrocher une bourse d''État, une place « aide/FPP » (partiellement payante) ou t''inscrire à titre payant. Toutes les démarches se font sur la plateforme officielle apresmonbac.bj après le bac.')
