INSERT INTO universites (slug, nom, description, ville, site_web, annee_creation, statut, contact_email, contact_telephone, stats_etudiants, stats_ecoles, stats_campuses, histoire, presentation, admission_info)
VALUES ('up', 'Université de Parakou', 'L''UP, c''est la grande université publique du Nord-Bénin. Elle a été créée pour que les bacheliers des départements septentrionaux n''aient plus à descendre jusqu''à Cotonou pour poursuivre de bonnes études, et elle s''est taillé une vraie réputation en médecine, en agronomie et en économie.', 'Parakou', NULL, 2001, 'Publique', NULL, NULL, NULL, '9', NULL, 'Créée en 2001 dans la foulée de la réforme qui a aussi vu naître l''UAC sous son nom actuel, l''Université de Parakou répondait à un besoin clair : rapprocher l''enseignement supérieur public des populations du Nord. Depuis, elle n''a cessé de grandir, avec l''ouverture d''une faculté de médecine, d''un IUT et de plusieurs écoles spécialisées.', 'L''UP couvre l''agronomie (Faculté d''Agronomie), la santé (Faculté de Médecine, IFSIO, ENATSE), l''économie et la gestion (FASEG, IUT), le droit (FDSP) ainsi que les lettres et sciences humaines (FLASH). Une université à taille humaine, mais avec une offre déjà très complète.', 'Comme partout ailleurs dans le public, l''entrée se fait par classement national du bac (la majorité des filières) ou par concours (santé, notamment). Bourses d''État, places FPP ou inscription payante : tout dépend de ton classement et des quotas fixés chaque année. Les choix se font sur apresmonbac.bj.')
