INSERT INTO universites (slug, nom, description, ville, site_web, annee_creation, statut, contact_email, contact_telephone, stats_etudiants, stats_ecoles, stats_campuses, histoire, presentation, admission_info)
VALUES ('uadc', 'Université Africaine de Développement Coopératif', 'L''UADC forme aux métiers de l''économie sociale et solidaire : coopératives, mutuelles, microfinance, développement local. Une université un peu différente des autres, pensée pour celles et ceux qui veulent travailler avec et pour les communautés plutôt que dans le circuit classique.', NULL, NULL, NULL, 'Publique / à titre payant', NULL, NULL, NULL, '3', NULL, 'L''UADC a été créée pour répondre à un besoin bien précis : professionnaliser les métiers du coopérativisme et du développement local en Afrique, un secteur longtemps laissé de côté par l''enseignement supérieur classique.', 'Trois UFR structurent l''université : l''UFR Économie et Gestion Coopératives, l''UFR Financement et Micro-financement, et l''UFR Développement. On y apprend à monter et gérer des coopératives, des systèmes de microfinance, des mutuelles de santé, ou encore à piloter des projets de développement local et de décentralisation.', 'L''inscription à l''UADC se fait à titre payant : les candidats intéressés doivent se rapprocher directement de la scolarité de l''université pour connaître les modalités précises.')
