INSERT INTO universites (slug, nom, description, ville, site_web, annee_creation, statut, contact_email, contact_telephone, stats_etudiants, stats_ecoles, stats_campuses, histoire, presentation, admission_info)
VALUES ('iuep', 'Institut Universitaire d''Enseignement Professionnel', 'L''IUEP forme aux métiers de l''agriculture dans une logique très concrète et professionnalisante, pour des bacheliers qui veulent aller vite vers le terrain plutôt que de multiplier les années de théorie.', NULL, NULL, NULL, 'Publique', NULL, NULL, NULL, '1', NULL, NULL, 'Un seul grand domaine de formation ici : les métiers de l''agriculture, avec une pédagogie tournée vers la pratique et l''insertion professionnelle rapide.', 'L''entrée se fait sur concours, ouvert aux bacheliers C, D et DEAT (Agriculture générale). Des bourses d''État sont attribuées selon les quotas fixés chaque année, via apresmonbac.bj.')
