INSERT INTO universites (slug, nom, description, ville, site_web, annee_creation, statut, contact_email, contact_telephone, stats_etudiants, stats_ecoles, stats_campuses, histoire, presentation, admission_info)
VALUES ('seme-city', 'Sèmè City', 'Sèmè City, c''est le pôle d''innovation et d''enseignement supérieur nouvelle génération du Bénin, pensé pour coller aux métiers de demain : design, numérique, informatique. Un cadre plus moderne, pensé aussi pour attirer des partenaires internationaux.', 'Sèmè-Podji', NULL, NULL, 'Établissements à titre payant', NULL, NULL, NULL, '2', NULL, NULL, 'Deux écoles y sont installées pour l''instant : Africa Design School, pour se former au design, et l''École de l''Innovation et de l''Expertise en Informatique (EPITECH), pour les métiers du numérique et de l''informatique.', 'Ces établissements fonctionnent à titre payant. Les candidats intéressés sont invités à se rapprocher directement de Sèmè City pour connaître les modalités d''inscription.')
