-- ---------- ECOLES ----------
INSERT INTO ecoles (slug, universite_id, nom, description, programmes_count)
VALUES ('institut-regional-de-sante-publique-irsp', (SELECT id FROM universites WHERE slug = 'uac'), 'Institut Régional de Santé Publique (IRSP)', 'Rattaché de l''UAC, IRSP (Institut Régional de Santé Publique) propose une formation de niveau licence : « Santé publique polyvalente ». De quoi te lancer directement dans la vie active ou continuer vers un master.', 1)
