INSERT INTO ecoles (slug, universite_id, nom, description, programmes_count)
VALUES ('faculte-des-lettres-arts-et-sciences-humaines-adjarra-flash-adjarra', (SELECT id FROM universites WHERE slug = 'uac'), 'Faculté des Lettres, Arts et Sciences Humaines Adjarra (FLASH-Adjarra)', 'FLASH-Adjarra (Faculté des Lettres, Arts et Sciences Humaines Adjarra) fait partie des établissements de l''UAC. On y prépare concrètement à des filières comme « Géographie et Aménagement du Territoire » ou « Socio-Anthropologie », avec un vrai accent mis sur les débouchés professionnels.', 2)
ON CONFLICT (slug) DO UPDATE SET
