INSERT INTO ecoles (slug, universite_id, nom, description, programmes_count)
VALUES ('institut-de-mathematiques-et-de-sciences-physiques-imsp', (SELECT id FROM universites WHERE slug = 'uac'), 'Institut de Mathématiques et de Sciences Physiques (IMSP)', 'IMSP (Institut de Mathématiques et de Sciences Physiques), c''est une école de l''UAC. Ici, tu as le choix entre une seule filière : « Classes préparatoires Mathématiques, Physique-Chimie et Sciences de l''Ingénieur (MPSI) et Physique-Chimie et Science de l''Ingénieur (PCSI) ». Une équipe qui sait ce qu''elle veut former, et qui le fait sérieusement.', 1)
