INSERT INTO ecoles (slug, universite_id, nom, description, programmes_count)
VALUES ('faculte-des-lettres-arts-langues-et-communications-fllac', (SELECT id FROM universites WHERE slug = 'uac'), 'Faculté des Lettres, Arts, Langues et Communications (FLLAC)', 'FLLAC (Faculté des Lettres, Arts, Langues et Communications) fait partie des établissements de l''UAC. On y prépare concrètement à des filières comme « Allemand », « Anglais », « Espagnol », « Lettres Modernes » ou « Sciences du Langage et de la Communication », avec un vrai accent mis sur les débouchés professionnels.', 5)
