INSERT INTO ecoles (slug, universite_id, nom, description, programmes_count)
VALUES ('institut-national-des-metiers-darts-darcheologie-et-de-la-culture-inmaac', (SELECT id FROM universites WHERE slug = 'uac'), 'Institut National des Métiers d''Arts, d''Archéologie et de la Culture (INMAAC)', 'INMAAC (Institut National des Métiers d''Arts, d''Archéologie et de la Culture), c''est une école de l''UAC. Ici, tu as le choix entre 5 filières : « Administration Culturelle », « Arts dramatiques », « Arts Plastiques », « Musique et Musicologie » ou « Cinéma et Audiovisuel ». Une équipe qui sait ce qu''elle veut former, et qui le fait sérieusement.', 5)
