INSERT INTO ecoles (slug, universite_id, nom, description, programmes_count)
VALUES ('centre-inter-facultaire-de-formation-et-de-recherche-en-environnement-pour-le-de', (SELECT id FROM universites WHERE slug = 'uac'), 'Centre Inter-Facultaire de Formation et de Recherche en Environnement pour le Développement Durable (CIFRED)', 'CIFRED (Centre Inter-Facultaire de Formation et de Recherche en Environnement pour le Développement Durable), c''est une école de l''UAC. Ici, tu as le choix entre une seule filière : « Environnement, Hygiène et Santé publique ». Une équipe qui sait ce qu''elle veut former, et qui le fait sérieusement.', 1)
