INSERT INTO ecoles (slug, universite_id, nom, description, programmes_count)
VALUES ('institut-du-cadre-de-vie-igate', (SELECT id FROM universites WHERE slug = 'uac'), 'Institut du Cadre de Vie (IGATE)', 'Rattaché de l''UAC, IGATE (Institut du Cadre de Vie) propose 4 formations de niveau licence : « Gestion du cadre de vie », « Gestion des changements climatiques et des écosystèmes », « Géomatique et Environnement » ou « Planification et Gestion des espaces urbains et ruraux ». De quoi te lancer directement dans la vie active ou continuer vers un master.', 4)
