INSERT INTO ecoles (slug, universite_id, nom, description, programmes_count)
VALUES ('institut-national-medico-sanitaire-inmes', (SELECT id FROM universites WHERE slug = 'uac'), 'Institut National Médico-Sanitaire (INMeS)', 'Rattaché de l''UAC, INMeS (Institut National Médico-Sanitaire) propose 2 formations de niveau licence : « Sciences Infirmières » ou « Sciences Obstétricales ». De quoi te lancer directement dans la vie active ou continuer vers un master.', 2)
