  programmes_count = EXCLUDED.programmes_count, updated_at = now();
INSERT INTO ecoles (slug, universite_id, nom, description, programmes_count)
VALUES ('institut-national-de-leau-ine', (SELECT id FROM universites WHERE slug = 'uac'), 'Institut National de l''Eau (INE)', 'INE (Institut National de l''Eau) fait partie des établissements de l''UAC. On y prépare concrètement à des filières comme « Hydrogéologie et Gestion intégrée des Ressources », « Ecohydrologie et Gestion intégrée des Ressources », « Gestion des crises et risques liés à l''eau et au climat », « Génie rural et Maîtrise de l''Eau », « Hydraulique et Assainissement » ou « Eau Hygiène et Assainissement (EHA) », avec un vrai accent mis sur les débouchés professionnels.', 6)
ON CONFLICT (slug) DO UPDATE SET
  universite_id = EXCLUDED.universite_id, nom = EXCLUDED.nom, description = EXCLUDED.description,
  programmes_count = EXCLUDED.programmes_count, updated_at = now();
INSERT INTO ecoles (slug, universite_id, nom, description, programmes_count)
VALUES ('ecole-nationale-deconomie-appliquee-et-de-management-eneam', (SELECT id FROM universites WHERE slug = 'uac'), 'École Nationale d''Économie Appliquée et de Management (ENEAM)', 'ENEAM (École Nationale d''Économie Appliquée et de Management), c''est une école de l''UAC. Ici, tu as le choix entre 15 filières : « Administration des Réseaux Informatiques », « Analyse Informatique et Programmation », « Assurance », « Banque et Finance de Marché », « Banque et Institutions des Micro finances », « Marketing », « Marketing (2e mention) », « Gestion des Ressources Humaines », « Gestion des Transports », « Gestion de Logistique », « Statistique Economique et Sectorielle », « Statistique Démographique et Sociale », « Planification Local et Gestion des Projets », « Planification et Economie du Développement Régional » ou « Développement Local et Régional ». Une équipe qui sait ce qu''elle veut former, et qui le fait sérieusement.', 15)
