-- ---------- FILIERES ----------
INSERT INTO filieres (slug, ecole_id, nom, description, duree_etudes, niveau_entree, conditions_admission, debouches, cout_annuel_info, competences_visees, programme_resume, bourse, aide_fpp, mode_entree, bac_recommande, matieres, careers)
VALUES ('sante-publique-polyvalente', (SELECT id FROM ecoles WHERE slug = 'institut-regional-de-sante-publique-irsp'), 'Santé publique polyvalente', 'Envie de te lancer dans « Santé publique polyvalente » ? C''est une formation de premier cycle (licence) donnée par IRSP (Institut Régional de Santé Publique), qui mise en t''appuyant surtout sur SVT, PCT et Maths et qui débouche notamment sur des métiers comme agent de santé communautaire.', '3 ans (Licence)', 'Baccalauréat C ou D', 'L''entrée se fait par le classement national du bac (ta moyenne au bac, calculée avec les coefficients de ta série, détermine ton rang). Cette année, 17 places boursières sont ouvertes sur cette filière ; au-delà, l''inscription se fait à titre payant.', 'Après cette formation, plusieurs portes s''ouvrent : tu peux te tourner vers agent de santé communautaire, responsable de surveillance épidémiologique, attaché de recherche en santé, assistant en planification, suivi et évaluation en santé ou agent d''hygiène et d''assainissement du milieu.', 'Selon ton classement : 17 places boursières (gratuité + allocation de l''État). Au-delà de ces quotas, l''inscription se fait à titre entièrement payant, selon le tarif fixé par l''établissement.', 'De bonnes bases en SVT, PCT et Maths, doublées d''une bonne dose de pratique : stages, travaux dirigés et projets concrets tout au long de la formation « Santé publique polyvalente ».', 'Au programme : SVT, PCT et Maths, ainsi que les enseignements transversaux propres à une licence (méthodologie, langues, stages...).', 17, 0, 'Classement', '["C","D"]'::jsonb, '["SVT","PCT","Maths"]'::jsonb, '[]'::jsonb)
ON CONFLICT (slug) DO UPDATE SET
  ecole_id = EXCLUDED.ecole_id, nom = EXCLUDED.nom, description = EXCLUDED.description, duree_etudes = EXCLUDED.duree_etudes,
  niveau_entree = EXCLUDED.niveau_entree, conditions_admission = EXCLUDED.conditions_admission, debouches = EXCLUDED.debouches,
  cout_annuel_info = EXCLUDED.cout_annuel_info, competences_visees = EXCLUDED.competences_visees, programme_resume = EXCLUDED.programme_resume,
  bourse = EXCLUDED.bourse, aide_fpp = EXCLUDED.aide_fpp, mode_entree = EXCLUDED.mode_entree, bac_recommande = EXCLUDED.bac_recommande,
  matieres = EXCLUDED.matieres, careers = EXCLUDED.careers, updated_at = now();
INSERT INTO filieres (slug, ecole_id, nom, description, duree_etudes, niveau_entree, conditions_admission, debouches, cout_annuel_info, competences_visees, programme_resume, bourse, aide_fpp, mode_entree, bac_recommande, matieres, careers)
VALUES ('geographie-et-amenagement-du-territoire', (SELECT id FROM ecoles WHERE slug = 'faculte-des-lettres-arts-et-sciences-humaines-adjarra-flash-adjarra'), 'Géographie et Aménagement du Territoire', 'La licence « Géographie et Aménagement du Territoire », proposée par FLASH-Adjarra (Faculté des Lettres, Arts et Sciences Humaines Adjarra), te forme en t''appuyant surtout sur Français, Hist-Géo/Anglais(DT/STI) et Maths, avec en ligne de mire des métiers comme enseignement. Trois ans après le bac, tu es prêt(e) à passer à l''action.', '3 ans (Licence)', 'Baccalauréat A1, A2, B ou D', 'L''entrée se fait par le classement national du bac (ta moyenne au bac, calculée avec les coefficients de ta série, détermine ton rang). Cette année, 60 places boursières et 340 places « aide/FPP » (partiellement payantes) sont ouvertes sur cette filière ; au-delà, l''inscription se fait à titre payant.', 'Côté débouchés, cette filière mène vers des métiers comme enseignement, laboratoires et institutions de recherche ou assainissement.', 'Selon ton classement : 60 places boursières (gratuité + allocation de l''État) et 340 places aide/FPP (scolarité partiellement prise en charge). Au-delà de ces quotas, l''inscription se fait à titre entièrement payant, selon le tarif fixé par l''établissement.', 'De bonnes bases en Français, Hist-Géo/Anglais(DT/STI) et Maths, doublées d''une bonne dose de pratique : stages, travaux dirigés et projets concrets tout au long de la formation « Géographie et Aménagement du Territoire ».', 'Au programme : Français, Hist-Géo/Anglais(DT/STI) et Maths, ainsi que les enseignements transversaux propres à une licence (méthodologie, langues, stages...).', 60, 340, 'Classement', '["A1","A2","B","D"]'::jsonb, '["Français","Hist-Géo/Anglais(DT/STI)","Maths"]'::jsonb, '[]'::jsonb)
ON CONFLICT (slug) DO UPDATE SET
  ecole_id = EXCLUDED.ecole_id, nom = EXCLUDED.nom, description = EXCLUDED.description, duree_etudes = EXCLUDED.duree_etudes,
  niveau_entree = EXCLUDED.niveau_entree, conditions_admission = EXCLUDED.conditions_admission, debouches = EXCLUDED.debouches,
  cout_annuel_info = EXCLUDED.cout_annuel_info, competences_visees = EXCLUDED.competences_visees, programme_resume = EXCLUDED.programme_resume,
  bourse = EXCLUDED.bourse, aide_fpp = EXCLUDED.aide_fpp, mode_entree = EXCLUDED.mode_entree, bac_recommande = EXCLUDED.bac_recommande,
  matieres = EXCLUDED.matieres, careers = EXCLUDED.careers, updated_at = now();
INSERT INTO filieres (slug, ecole_id, nom, description, duree_etudes, niveau_entree, conditions_admission, debouches, cout_annuel_info, competences_visees, programme_resume, bourse, aide_fpp, mode_entree, bac_recommande, matieres, careers)
VALUES ('socio-anthropologie', (SELECT id FROM ecoles WHERE slug = 'faculte-des-lettres-arts-et-sciences-humaines-adjarra-flash-adjarra'), 'Socio-Anthropologie', 'La licence « Socio-Anthropologie », proposée par FLASH-Adjarra (Faculté des Lettres, Arts et Sciences Humaines Adjarra), te forme en t''appuyant surtout sur Français, Hist-Géo/Anglais(DT/STI) et Maths, avec en ligne de mire des métiers comme interprétariat. Trois ans après le bac, tu es prêt(e) à passer à l''action.', '3 ans (Licence)', 'Baccalauréat A1, A2, B, C, D, DEAT(toutes spécialités) ou DT/STI', 'L''entrée se fait par le classement national du bac (ta moyenne au bac, calculée avec les coefficients de ta série, détermine ton rang). Cette année, 63 places boursières et 323 places « aide/FPP » (partiellement payantes) sont ouvertes sur cette filière ; au-delà, l''inscription se fait à titre payant.', 'Côté débouchés, cette filière mène vers des métiers comme interprétariat, tourisme ou enseignements.', 'Selon ton classement : 63 places boursières (gratuité + allocation de l''État) et 323 places aide/FPP (scolarité partiellement prise en charge). Au-delà de ces quotas, l''inscription se fait à titre entièrement payant, selon le tarif fixé par l''établissement.', 'De bonnes bases en Français, Hist-Géo/Anglais(DT/STI) et Maths, doublées d''une bonne dose de pratique : stages, travaux dirigés et projets concrets tout au long de la formation « Socio-Anthropologie ».', 'Au programme : Français, Hist-Géo/Anglais(DT/STI), Maths et pour DEAT: toutes les 3 matières écrites, ainsi que les enseignements transversaux propres à une licence (méthodologie, langues, stages...).', 63, 323, 'Classement', '["A1","A2","B","C","D","DEAT(toutes spécialités)","DT/STI"]'::jsonb, '["Français","Hist-Géo/Anglais(DT/STI)","Maths","pour DEAT: toutes les 3 matières écrites"]'::jsonb, '[]'::jsonb)
