INSERT INTO filieres (slug, ecole_id, nom, description, duree_etudes, niveau_entree, conditions_admission, debouches, cout_annuel_info, competences_visees, programme_resume, bourse, aide_fpp, mode_entree, bac_recommande, matieres, careers)
VALUES ('classes-preparatoires-mathematiques-physique-chimie-et-sciences-de-lingenieur-mp', (SELECT id FROM ecoles WHERE slug = 'institut-de-mathematiques-et-de-sciences-physiques-imsp'), 'Classes préparatoires Mathématiques, Physique-Chimie et Sciences de l''Ingénieur (MPSI) et Physique-Chimie et Science de l''Ingénieur (PCSI)', '« Classes préparatoires Mathématiques, Physique-Chimie et Sciences de l''Ingénieur (MPSI) et Physique-Chimie et Science de l''Ingénieur (PCSI) », proposée par IMSP (Institut de Mathématiques et de Sciences Physiques), ce sont deux années de classes préparatoires intégrées en t''appuyant surtout sur Maths, PCT et Français. Objectif : intégrer ensuite un cycle ingénieur (3 années supplémentaires), avec des suites comme entrée dans les grandes écoles d''ingénieurs.', '2 ans de classes préparatoires, puis 3 ans en cycle ingénieur', 'Baccalauréat C, D, E ou F', 'L''entrée se fait par le classement national du bac (ta moyenne au bac, calculée avec les coefficients de ta série, détermine ton rang). Cette année, 134 places boursières et 667 places « aide/FPP » (partiellement payantes) sont ouvertes sur cette filière ; au-delà, l''inscription se fait à titre payant.', 'Côté débouchés, cette filière mène vers des métiers comme entrée dans les grandes écoles d''ingénieurs ou entrée dans les Masters de Mathématiques, de Physique et Informatique.', 'Selon ton classement : 134 places boursières (gratuité + allocation de l''État) et 667 places aide/FPP (scolarité partiellement prise en charge). Au-delà de ces quotas, l''inscription se fait à titre entièrement payant, selon le tarif fixé par l''établissement.', 'De bonnes bases en Maths, PCT et Français, doublées d''une bonne dose de pratique : stages, travaux dirigés et projets concrets tout au long de la formation « Classes préparatoires Mathématiques, Physique-Chimie et Sciences de l''Ingénieur (MPSI) et Physique-Chimie et Science de l''Ingénieur (PCSI) ».', 'Au programme : Maths, PCT et Français, ainsi que les enseignements transversaux propres à une licence (méthodologie, langues, stages...).', 134, 667, 'Classement', '["C","D","E","F"]'::jsonb, '["Maths","PCT","Français"]'::jsonb, '[]'::jsonb)
