INSERT INTO filieres (slug, ecole_id, nom, description, duree_etudes, niveau_entree, conditions_admission, debouches, cout_annuel_info, competences_visees, programme_resume, bourse, aide_fpp, mode_entree, bac_recommande, matieres, careers)
VALUES ('allemand', (SELECT id FROM ecoles WHERE slug = 'faculte-des-lettres-arts-langues-et-communications-fllac'), 'Allemand', 'Envie de te lancer dans « Allemand » ? C''est une formation de premier cycle (licence) donnée par FLLAC (Faculté des Lettres, Arts, Langues et Communications), qui mise en t''appuyant surtout sur Allemand(LV1), Anglais(LV2)/Hist-Géo(B) et Français et qui débouche notamment sur des métiers comme interprétariat.', '3 ans (Licence)', 'Baccalauréat A1, A2 ou B', 'L''entrée se fait par le classement national du bac (ta moyenne au bac, calculée avec les coefficients de ta série, détermine ton rang). Cette année, 12 places boursières et 75 places « aide/FPP » (partiellement payantes) sont ouvertes sur cette filière ; au-delà, l''inscription se fait à titre payant.', 'Une fois diplômé(e), tu peux viser des postes ou des activités comme interprétariat, enseignements dans les collèges et lycées ou traducteur correcteur des maisons d''édition.', 'Selon ton classement : 12 places boursières (gratuité + allocation de l''État) et 75 places aide/FPP (scolarité partiellement prise en charge). Au-delà de ces quotas, l''inscription se fait à titre entièrement payant, selon le tarif fixé par l''établissement.', 'De bonnes bases en Allemand(LV1), Anglais(LV2)/Hist-Géo(B) et Français, doublées d''une bonne dose de pratique : stages, travaux dirigés et projets concrets tout au long de la formation « Allemand ».', 'Au programme : Allemand(LV1), Anglais(LV2)/Hist-Géo(B) et Français, ainsi que les enseignements transversaux propres à une licence (méthodologie, langues, stages...).', 12, 75, 'Classement', '["A1","A2","B"]'::jsonb, '["Allemand(LV1)","Anglais(LV2)/Hist-Géo(B)","Français"]'::jsonb, '[]'::jsonb)
