INSERT INTO filieres (slug, ecole_id, nom, description, duree_etudes, niveau_entree, conditions_admission, debouches, cout_annuel_info, competences_visees, programme_resume, bourse, aide_fpp, mode_entree, bac_recommande, matieres, careers)
VALUES ('marketing', (SELECT id FROM ecoles WHERE slug = 'ecole-nationale-deconomie-appliquee-et-de-management-eneam'), 'Marketing', '« Marketing », c''est la filière de ENEAM (École Nationale d''Économie Appliquée et de Management) pour celles et ceux qui veulent progresser en s''appuyant surtout sur Economie(B)/Maths(C-D), Etude de Cas et Français, avec des débouchés concrets comme marketing et Communication Commerciale.', '3 ans (Licence)', 'Baccalauréat B, C, D, G3 ou DT/CoM', 'L''entrée se fait par le classement national du bac (ta moyenne au bac, calculée avec les coefficients de ta série, détermine ton rang). Cette année, 8 places boursières sont ouvertes sur cette filière ; au-delà, l''inscription se fait à titre payant.', 'Après cette formation, plusieurs portes s''ouvrent : tu peux te tourner vers marketing et Communication Commerciale, responsable du développement commercial, chargé de clientèle, chargé d''études marketing, chef de publicité, marketing Digital and Community Management, responsable Marketing Digital/Digital Brand Manager, chargé de la stratégie mobile, chargé de communication web digital/CRM, responsable marketing relationnel/CRM, marketing business analyst, data miner/Data analyst, chef de projet Web, responsable e-Commerce ou digital planner.', 'Selon ton classement : 8 places boursières (gratuité + allocation de l''État). Au-delà de ces quotas, l''inscription se fait à titre entièrement payant, selon le tarif fixé par l''établissement.', 'De bonnes bases en Economie(B)/Maths(C-D), Etude de Cas, Français et Anglais(LV pour B), doublées d''une bonne dose de pratique : stages, travaux dirigés et projets concrets tout au long de la formation « Marketing ».', 'Au programme : Economie(B)/Maths(C-D), Etude de Cas, Français, Anglais(LV pour B), Organisation, Mercatique administration des ressources, Français et pour DT/CoM: Techniques Compta, ainsi que les enseignements transversaux propres à une licence (méthodologie, langues, stages...).', 8, 0, 'Classement', '["B","C","D","G3","DT/CoM"]'::jsonb, '["Economie(B)/Maths(C-D)","Etude de Cas","Français","Anglais(LV pour B)","pour DT/CoM: Techniques Compta","Organisation","Mercatique administration des ressources","Français"]'::jsonb, '[]'::jsonb)
