INSERT INTO filieres (slug, ecole_id, nom, description, duree_etudes, niveau_entree, conditions_admission, debouches, cout_annuel_info, competences_visees, programme_resume, bourse, aide_fpp, mode_entree, bac_recommande, matieres, careers)
VALUES ('gestion-financiere-et-comptable', (SELECT id FROM ecoles WHERE slug = 'ecole-du-patrimoine-africain-epa'), 'Gestion Financière et Comptable', 'Envie de te lancer dans « Gestion Financière et Comptable » ? C''est une formation de premier cycle (licence) donnée par EPA (École du Patrimoine Africain), qui mise en t''appuyant surtout sur Maths, Français et Anglais(UV1 pour les G2) et qui débouche notamment sur des métiers comme comptable.', '3 ans (Licence)', 'Baccalauréat C, D ou G2', 'L''entrée se fait par le classement national du bac (ta moyenne au bac, calculée avec les coefficients de ta série, détermine ton rang). Cette année, 20 places boursières et 33 places « aide/FPP » (partiellement payantes) sont ouvertes sur cette filière ; au-delà, l''inscription se fait à titre payant.', 'Une fois diplômé(e), tu peux viser des postes ou des activités comme comptable, responsable financier, auditeur financier ou auditeur interne.', 'Selon ton classement : 20 places boursières (gratuité + allocation de l''État) et 33 places aide/FPP (scolarité partiellement prise en charge). Au-delà de ces quotas, l''inscription se fait à titre entièrement payant, selon le tarif fixé par l''établissement.', 'De bonnes bases en Maths, Français et Anglais(UV1 pour les G2), doublées d''une bonne dose de pratique : stages, travaux dirigés et projets concrets tout au long de la formation « Gestion Financière et Comptable ».', 'Au programme : Maths, Français et Anglais(UV1 pour les G2), ainsi que les enseignements transversaux propres à une licence (méthodologie, langues, stages...).', 20, 33, 'Classement', '["C","D","G2"]'::jsonb, '["Maths","Français","Anglais(UV1 pour les G2)"]'::jsonb, '[]'::jsonb)
