INSERT INTO filieres (slug, ecole_id, nom, description, duree_etudes, niveau_entree, conditions_admission, debouches, cout_annuel_info, competences_visees, programme_resume, bourse, aide_fpp, mode_entree, bac_recommande, matieres, careers)
VALUES ('gestion-du-patrimoine-culturel', (SELECT id FROM ecoles WHERE slug = 'ecole-du-patrimoine-africain-epa'), 'Gestion du patrimoine culturel', 'Envie de te lancer dans « Gestion du patrimoine culturel » ? C''est une formation de premier cycle (licence) donnée par EPA (École du Patrimoine Africain), qui mise en t''appuyant surtout sur Hist-Géo(Etude de cas pour les G), Anglais(UV1 pour les A et B) et qui débouche notamment sur des métiers comme droit du patrimoine.', '3 ans (Licence)', 'Baccalauréat A1, A2, B, C, G1, G3 ou DT tourisme', 'L''entrée se fait par le classement national du bac (ta moyenne au bac, calculée avec les coefficients de ta série, détermine ton rang). Cette année, 82 places boursières et 667 places « aide/FPP » (partiellement payantes) sont ouvertes sur cette filière ; au-delà, l''inscription se fait à titre payant.', 'Une fois diplômé(e), tu peux viser des postes ou des activités comme droit du patrimoine, patrimoniaires de musées ou gestionnaires de patrimoine culturel.', 'Selon ton classement : 82 places boursières (gratuité + allocation de l''État) et 667 places aide/FPP (scolarité partiellement prise en charge). Au-delà de ces quotas, l''inscription se fait à titre entièrement payant, selon le tarif fixé par l''établissement.', 'De bonnes bases en Hist-Géo(Etude de cas pour les G), Anglais(UV1 pour les A, B) et législation du tourisme, doublées d''une bonne dose de pratique : stages, travaux dirigés et projets concrets tout au long de la formation « Gestion du patrimoine culturel ».', 'Au programme : Hist-Géo(Etude de cas pour les G), Anglais(UV1 pour les A, B), législation du tourisme et pour DT tourisme: Mercatique du tourisme, ainsi que les enseignements transversaux propres à une licence (méthodologie, langues, stages...).', 82, 667, 'Classement', '["A1","A2","B","C","G1","G3","DT tourisme"]'::jsonb, '["Hist-Géo(Etude de cas pour les G)","Anglais(UV1 pour les A","B)","pour DT tourisme: Mercatique du tourisme","législation du tourisme"]'::jsonb, '[]'::jsonb)
