INSERT INTO filieres (slug, ecole_id, nom, description, duree_etudes, niveau_entree, conditions_admission, debouches, cout_annuel_info, competences_visees, programme_resume, bourse, aide_fpp, mode_entree, bac_recommande, matieres, careers)
VALUES ('philosophie', (SELECT id FROM ecoles WHERE slug = 'faculte-des-sciences-humaines-et-sociales-fashs-calavi'), 'Philosophie', 'Envie de te lancer dans « Philosophie » ? C''est une formation de premier cycle (licence) donnée par l''Faculté des Sciences Humaines et Sociales, qui mise en t''appuyant surtout sur Français, Anglais(UV1 pour A) et Philo/Droit Admin et qui débouche notamment sur des métiers comme enseignements dans les collèges et lycées.', '3 ans (Licence)', 'Baccalauréat A1, A2, B, C ou D', 'L''entrée se fait par le classement national du bac (ta moyenne au bac, calculée avec les coefficients de ta série, détermine ton rang). Cette année, 37 places boursières et 176 places « aide/FPP » (partiellement payantes) sont ouvertes sur cette filière ; au-delà, l''inscription se fait à titre payant.', 'Après cette formation, plusieurs portes s''ouvrent : tu peux te tourner vers enseignements dans les collèges et lycées.', 'Selon ton classement : 37 places boursières (gratuité + allocation de l''État) et 176 places aide/FPP (scolarité partiellement prise en charge). Au-delà de ces quotas, l''inscription se fait à titre entièrement payant, selon le tarif fixé par l''établissement.', 'De bonnes bases en Français, Anglais(UV1 pour A), Philo/Droit Admin et Philo(pour les G1, doublées d''une bonne dose de pratique : stages, travaux dirigés et projets concrets tout au long de la formation « Philosophie ».', 'Au programme : Français, Anglais(UV1 pour A), Philo/Droit Admin, Philo(pour les G1 et G3), ainsi que les enseignements transversaux propres à une licence (méthodologie, langues, stages...).', 37, 176, 'Classement', '["A1","A2","B","C","D"]'::jsonb, '["Français","Anglais(UV1 pour A)","Philo/Droit Admin","Philo(pour les G1","G3)"]'::jsonb, '[]'::jsonb)
