INSERT INTO filieres (slug, ecole_id, nom, description, duree_etudes, niveau_entree, conditions_admission, debouches, cout_annuel_info, competences_visees, programme_resume, bourse, aide_fpp, mode_entree, bac_recommande, matieres, careers)
VALUES ('entreprenariat-social', (SELECT id FROM ecoles WHERE slug = 'ecole-normale-superieure-porto-novo-ens'), 'Entreprenariat social', 'Envie de te lancer dans « Entreprenariat social » ? C''est une formation de premier cycle (licence) donnée par ENS (École Normale Supérieure / Porto-Novo), qui mise en t''appuyant surtout sur Français, Anglais(UV1) et Philo et qui débouche notamment sur des métiers comme technicien Supérieur d''Action Socio-Educative.', '3 ans (Licence)', 'Baccalauréat A1, A2, B, C ou D', 'L''entrée se fait par le classement national du bac (ta moyenne au bac, calculée avec les coefficients de ta série, détermine ton rang). Cette année, 14 places boursières sont ouvertes sur cette filière ; au-delà, l''inscription se fait à titre payant.', 'Après cette formation, plusieurs portes s''ouvrent : tu peux te tourner vers technicien Supérieur d''Action Socio-Educative ou administrateur d''Action Socio-Educative.', 'Selon ton classement : 14 places boursières (gratuité + allocation de l''État). Au-delà de ces quotas, l''inscription se fait à titre entièrement payant, selon le tarif fixé par l''établissement.', 'De bonnes bases en Français, Anglais(UV1) et Philo, doublées d''une bonne dose de pratique : stages, travaux dirigés et projets concrets tout au long de la formation « Entreprenariat social ».', 'Au programme : Français, Anglais(UV1) et Philo, ainsi que les enseignements transversaux propres à une licence (méthodologie, langues, stages...).', 14, 0, 'Classement', '["A1","A2","B","C","D"]'::jsonb, '["Français","Anglais(UV1)","Philo"]'::jsonb, '[]'::jsonb)
