INSERT INTO filieres (slug, ecole_id, nom, description, duree_etudes, niveau_entree, conditions_admission, debouches, cout_annuel_info, competences_visees, programme_resume, bourse, aide_fpp, mode_entree, bac_recommande, matieres, careers)
VALUES ('sciences-economiques-et-de-gestion-tronc-commun', (SELECT id FROM ecoles WHERE slug = 'faculte-des-sciences-economiques-et-de-gestion-faseg'), 'Sciences Economiques et de Gestion (Tronc commun)', 'La licence « Sciences Economiques et de Gestion (Tronc commun) », proposée par FASEG (Faculté des Sciences Economiques et de Gestion), te forme en t''appuyant surtout sur Maths(C-D)/Maths(B), Etude de cas(G)/Economie et PCT, avec en ligne de mire des métiers comme services décconcentrés de l''Etat, Collectivités locales, associations et ONG. Trois ans après le bac, tu es prêt(e) à passer à l''action.', '3 ans (Licence)', 'Baccalauréat B, C, D, G2, G3 ou DT/CoM', 'L''entrée se fait par le classement national du bac (ta moyenne au bac, calculée avec les coefficients de ta série, détermine ton rang). Cette année, 207 places boursières et 1407 places « aide/FPP » (partiellement payantes) sont ouvertes sur cette filière ; au-delà, l''inscription se fait à titre payant.', 'Après cette formation, plusieurs portes s''ouvrent : tu peux te tourner vers services décconcentrés de l''Etat, Collectivités locales, associations et ONG, analystes, statisticiens, Comptable, planificateur et Gestion des Ressources financières, statistique agricole, analyse des projets agricoles, gestion des structures de collectivités, chargé des études et de la prospective économique des collectivités, economiste de marché, conseiller en Microfinance, entrepreneur, gestionnaire des PME, comptable dans les structures financières, assistant Auditeur, agent de banque ou agent d''assurance.', 'Selon ton classement : 207 places boursières (gratuité + allocation de l''État) et 1407 places aide/FPP (scolarité partiellement prise en charge). Au-delà de ces quotas, l''inscription se fait à titre entièrement payant, selon le tarif fixé par l''établissement.', 'De bonnes bases en Maths(C-D)/Maths(B), Etude de cas(G)/Economie, PCT et Français, doublées d''une bonne dose de pratique : stages, travaux dirigés et projets concrets tout au long de la formation « Sciences Economiques et de Gestion (Tronc commun) ».', 'Au programme : Maths(C-D)/Maths(B), Etude de cas(G)/Economie, PCT, Français, Organisation, Mercatique, administration rationnelle des ressources, Français et pour DT/Com: Tech Compta, ainsi que les enseignements transversaux propres à une licence (méthodologie, langues, stages...).', 207, 1407, 'Classement', '["B","C","D","G2","G3","DT/CoM"]'::jsonb, '["Maths(C-D)/Maths(B)","Etude de cas(G)/Economie","PCT","Français","pour DT/Com: Tech Compta","Organisation","Mercatique","administration rationnelle des ressources","Français"]'::jsonb, '[]'::jsonb)
