INSERT INTO filieres (slug, ecole_id, nom, description, duree_etudes, niveau_entree, conditions_admission, debouches, cout_annuel_info, competences_visees, programme_resume, bourse, aide_fpp, mode_entree, bac_recommande, matieres, careers)
VALUES ('microbiologie-et-biotechnologie-alimentaire', (SELECT id FROM ecoles WHERE slug = 'faculte-des-sciences-techniques-fast'), 'Microbiologie et Biotechnologie Alimentaire', 'La licence « Microbiologie et Biotechnologie Alimentaire », proposée par FAST (Faculté des Sciences Techniques), te forme en t''appuyant surtout sur SVT, PCT et Français, avec en ligne de mire des métiers comme chef de production dans les industries. Trois ans après le bac, tu es prêt(e) à passer à l''action.', '3 ans (Licence)', 'Baccalauréat C, D, DEAT/Nutrition ou Technologie Alimentaire', 'L''entrée se fait par le classement national du bac (ta moyenne au bac, calculée avec les coefficients de ta série, détermine ton rang). Cette année, 17 places boursières sont ouvertes sur cette filière ; au-delà, l''inscription se fait à titre payant.', 'Après cette formation, plusieurs portes s''ouvrent : tu peux te tourner vers chef de production dans les industries, laboratoire en Contrôle de qualité, transformations agroalimentaires, auditeur de qualité ou formateurs agricoles.', 'Selon ton classement : 17 places boursières (gratuité + allocation de l''État). Au-delà de ces quotas, l''inscription se fait à titre entièrement payant, selon le tarif fixé par l''établissement.', 'De bonnes bases en SVT, PCT, Français et DEAT: 3 matières écrites, doublées d''une bonne dose de pratique : stages, travaux dirigés et projets concrets tout au long de la formation « Microbiologie et Biotechnologie Alimentaire ».', 'Au programme : SVT, PCT, Français et DEAT: 3 matières écrites, ainsi que les enseignements transversaux propres à une licence (méthodologie, langues, stages...).', 17, 0, 'Classement', '["C","D","DEAT/Nutrition","Technologie Alimentaire"]'::jsonb, '["SVT","PCT","Français","DEAT: 3 matières écrites"]'::jsonb, '[]'::jsonb)
ON CONFLICT (slug) DO UPDATE SET
  ecole_id = EXCLUDED.ecole_id, nom = EXCLUDED.nom, description = EXCLUDED.description, duree_etudes = EXCLUDED.duree_etudes,
