INSERT INTO filieres (slug, ecole_id, nom, description, duree_etudes, niveau_entree, conditions_admission, debouches, cout_annuel_info, competences_visees, programme_resume, bourse, aide_fpp, mode_entree, bac_recommande, matieres, careers)
VALUES ('hydrobiologie-appliquee', (SELECT id FROM ecoles WHERE slug = 'faculte-des-sciences-techniques-fast'), 'Hydrobiologie Appliquée', '« Hydrobiologie Appliquée », c''est la filière de FAST (Faculté des Sciences Techniques) pour celles et ceux qui veulent progresser en s''appuyant surtout sur SVT, PCT et Français, avec des débouchés concrets comme techniciens de laboratoire de biologie.', '3 ans (Licence)', 'Baccalauréat C, D, DEAT/Pêche ou aquaculture', 'L''entrée se fait par le classement national du bac (ta moyenne au bac, calculée avec les coefficients de ta série, détermine ton rang). Cette année, 16 places boursières sont ouvertes sur cette filière ; au-delà, l''inscription se fait à titre payant.', 'Côté débouchés, cette filière mène vers des métiers comme techniciens de laboratoire de biologie, spécialiste de la qualité de l''eau et surveillance des écosystèmes, chef Production en pisciculture, pêche et Aquaculture, technicien en Aménagement des zones humides, technicien en Aquariologie ou technicien Inspection des produits halieutiques.', 'Selon ton classement : 16 places boursières (gratuité + allocation de l''État). Au-delà de ces quotas, l''inscription se fait à titre entièrement payant, selon le tarif fixé par l''établissement.', 'De bonnes bases en SVT, PCT, Français et DEAT: 3 matières écrites, doublées d''une bonne dose de pratique : stages, travaux dirigés et projets concrets tout au long de la formation « Hydrobiologie Appliquée ».', 'Au programme : SVT, PCT, Français et DEAT: 3 matières écrites, ainsi que les enseignements transversaux propres à une licence (méthodologie, langues, stages...).', 16, 0, 'Classement', '["C","D","DEAT/Pêche","aquaculture"]'::jsonb, '["SVT","PCT","Français","DEAT: 3 matières écrites"]'::jsonb, '[]'::jsonb)
