INSERT INTO filieres (slug, ecole_id, nom, description, duree_etudes, niveau_entree, conditions_admission, debouches, cout_annuel_info, competences_visees, programme_resume, bourse, aide_fpp, mode_entree, bac_recommande, matieres, careers)
VALUES ('langue-chinoise', (SELECT id FROM ecoles WHERE slug = 'institut-confucius'), 'Langue Chinoise', 'La licence « Langue Chinoise », proposée par l''Institut Confucius, te forme, avec en ligne de mire des métiers comme entreprise chinoise au Bénin ou dans la sous-région. Trois ans après le bac, tu es prêt(e) à passer à l''action.', '3 ans (Licence)', 'Baccalauréat A1, A2, B ou D', 'L''entrée se fait par le classement national du bac (ta moyenne au bac, calculée avec les coefficients de ta série, détermine ton rang). Les quotas de bourses et de places FPP sont fixés chaque année par le Ministère selon la filière.', 'Après cette formation, plusieurs portes s''ouvrent : tu peux te tourner vers entreprise chinoise au Bénin ou dans la sous-région, interprète ou guide touristique ou bourses d''études pour étudier dans des Universités chinoises.', 'Pas de quota de bourse communiqué pour cette filière dans le guide officiel : renseigne-toi sur apresmonbac.bj au moment de faire tes choix pour connaître les places disponibles de l''année.', 'Les bases théoriques et pratiques du métier, construites au fil des stages et travaux pratiques propres à la filière « Langue Chinoise ».', 'Le contenu précis du programme (matières, volumes horaires) est à demander directement à l''établissement.', 0, 0, 'Classement', '["A1","A2","B","D"]'::jsonb, '[]'::jsonb, '[]'::jsonb)
ON CONFLICT (slug) DO UPDATE SET
  ecole_id = EXCLUDED.ecole_id, nom = EXCLUDED.nom, description = EXCLUDED.description, duree_etudes = EXCLUDED.duree_etudes,
