INSERT INTO filieres (slug, ecole_id, nom, description, duree_etudes, niveau_entree, conditions_admission, debouches, cout_annuel_info, competences_visees, programme_resume, bourse, aide_fpp, mode_entree, bac_recommande, matieres, careers)
VALUES ('entreprenariat-et-gestion-des-entreprises-ege', (SELECT id FROM ecoles WHERE slug = 'faculte-de-sciences-economiques-et-de-gestion-faseg'), 'Entreprenariat et Gestion des Entreprises (EGE)', 'Envie de te lancer dans « Entreprenariat et Gestion des Entreprises (EGE) » ? C''est une formation de premier cycle (licence) donnée par FASEG (Faculté de Sciences Economiques et de Gestion) et qui débouche notamment sur des métiers comme auto emploi.', '3 ans (Licence)', 'Baccalauréat toutes séries confondues', 'L''entrée se fait par le classement national du bac (ta moyenne au bac, calculée avec les coefficients de ta série, détermine ton rang). Cette année, 21 places boursières et 57 places « aide/FPP » (partiellement payantes) sont ouvertes sur cette filière ; au-delà, l''inscription se fait à titre payant.', 'Côté débouchés, cette filière mène vers des métiers comme auto emploi, cabinets Conseils en Etudes de Faisabilité, appui Conseils en Gestion de la Qualité et des Innovations des plans d''affaires, cabinets d''Audit et Création, Gestion et mise à niveau (d''Entreprises) ou pME et PMI.', 'Selon ton classement : 21 places boursières (gratuité + allocation de l''État) et 57 places aide/FPP (scolarité partiellement prise en charge). Au-delà de ces quotas, l''inscription se fait à titre entièrement payant, selon le tarif fixé par l''établissement.', 'Les bases théoriques et pratiques du métier, construites au fil des stages et travaux pratiques propres à la filière « Entreprenariat et Gestion des Entreprises (EGE) ».', 'Le contenu précis du programme (matières, volumes horaires) est à demander directement à l''établissement.', 21, 57, 'Classement', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb)
