INSERT INTO filieres (slug, ecole_id, nom, description, duree_etudes, niveau_entree, conditions_admission, debouches, cout_annuel_info, competences_visees, programme_resume, bourse, aide_fpp, mode_entree, bac_recommande, matieres, careers)
VALUES ('marketing-et-management-des-organisations-mmo', (SELECT id FROM ecoles WHERE slug = 'faculte-de-sciences-economiques-et-de-gestion-faseg'), 'Marketing et Management des Organisations (MMO)', 'Envie de te lancer dans « Marketing et Management des Organisations (MMO) » ? C''est une formation de premier cycle (licence) donnée par FASEG (Faculté de Sciences Economiques et de Gestion), qui mise en t''appuyant surtout sur Mercatique, Organisation et Administration rationnelle des ressources et qui débouche notamment sur des métiers comme auto emploi.', '3 ans (Licence)', 'Baccalauréat B, C, D, G2, G3 ou DT/CoM', 'L''entrée se fait par le classement national du bac (ta moyenne au bac, calculée avec les coefficients de ta série, détermine ton rang). Cette année, 13 places boursières et 37 places « aide/FPP » (partiellement payantes) sont ouvertes sur cette filière ; au-delà, l''inscription se fait à titre payant.', 'Après cette formation, plusieurs portes s''ouvrent : tu peux te tourner vers auto emploi, cabinets Conseils en Management, cabinets Conseils en Marketing, cabinets d''Audit en Gestion, structures Chargées des Questions Liées aux Affaires (Ministères, Administrations), projets de Développement ou entreprises de tous Genres.', 'Selon ton classement : 13 places boursières (gratuité + allocation de l''État) et 37 places aide/FPP (scolarité partiellement prise en charge). Au-delà de ces quotas, l''inscription se fait à titre entièrement payant, selon le tarif fixé par l''établissement.', 'De bonnes bases en Mercatique, Organisation, Administration rationnelle des ressources et Français, doublées d''une bonne dose de pratique : stages, travaux dirigés et projets concrets tout au long de la formation « Marketing et Management des Organisations (MMO) ».', 'Au programme : Mercatique, Organisation, Administration rationnelle des ressources, Français et pour DT/Com: Tech Compta, ainsi que les enseignements transversaux propres à une licence (méthodologie, langues, stages...).', 13, 37, 'Classement', '["B","C","D","G2","G3","DT/CoM"]'::jsonb, '["pour DT/Com: Tech Compta","Mercatique","Organisation","Administration rationnelle des ressources","Français"]'::jsonb, '[]'::jsonb)
