INSERT INTO filieres (slug, ecole_id, nom, description, duree_etudes, niveau_entree, conditions_admission, debouches, cout_annuel_info, competences_visees, programme_resume, bourse, aide_fpp, mode_entree, bac_recommande, matieres, careers)
VALUES ('droit-prive', (SELECT id FROM ecoles WHERE slug = 'faculte-de-droit-et-sciences-politiques-fdsp'), 'Droit Privé', 'La licence « Droit Privé », proposée par FDSP (Faculté de Droit et Sciences Politiques), te forme en t''appuyant surtout sur Français, Philo/Etude de Cas(G) et Hist-Géo/Anglais(G), avec en ligne de mire des métiers comme attaché des services administratifs. Trois ans après le bac, tu es prêt(e) à passer à l''action.', '3 ans (Licence)', 'Baccalauréat A1, A2, B, C, D, G1, G2 ou G3', 'L''entrée se fait par le classement national du bac (ta moyenne au bac, calculée avec les coefficients de ta série, détermine ton rang). Cette année, 99 places boursières et 545 places « aide/FPP » (partiellement payantes) sont ouvertes sur cette filière ; au-delà, l''inscription se fait à titre payant.', 'Après cette formation, plusieurs portes s''ouvrent : tu peux te tourner vers attaché des services administratifs, juristes des affaires, greffier, collaborateurs de profession judiciaire (avocats, huissiers, notaires, Commissaires-priseurs), magistrature (à condition de compléter le cycle de master) ou consultant, policier, militaire.', 'Selon ton classement : 99 places boursières (gratuité + allocation de l''État) et 545 places aide/FPP (scolarité partiellement prise en charge). Au-delà de ces quotas, l''inscription se fait à titre entièrement payant, selon le tarif fixé par l''établissement.', 'De bonnes bases en Français, Philo/Etude de Cas(G) et Hist-Géo/Anglais(G), doublées d''une bonne dose de pratique : stages, travaux dirigés et projets concrets tout au long de la formation « Droit Privé ».', 'Au programme : Français, Philo/Etude de Cas(G) et Hist-Géo/Anglais(G), ainsi que les enseignements transversaux propres à une licence (méthodologie, langues, stages...).', 99, 545, 'Classement', '["A1","A2","B","C","D","G1","G2","G3"]'::jsonb, '["Français","Philo/Etude de Cas(G)","Hist-Géo/Anglais(G)"]'::jsonb, '[]'::jsonb)
