VALUES ('production-animale', (SELECT id FROM ecoles WHERE slug = 'ecole-normale-superieure-de-lenseignement-technique-enset'), 'Production Animale', 'La licence « Production Animale », proposée par ENSET (École Normale Supérieure de l''Enseignement Technique), te forme en t''appuyant surtout sur Culture générale et SVT(D)/PCT(D), avec en ligne de mire des métiers comme professeur adjoint des Lycées et Collèges. Trois ans après le bac, tu es prêt(e) à passer à l''action.', '3 ans (Licence)', 'Baccalauréat C, D ou DEAT/PA', 'L''entrée se fait par un concours d''entrée. Cette année, 13 places boursières sont ouvertes sur cette filière ; au-delà, l''inscription se fait à titre payant.', 'Côté débouchés, cette filière mène vers des métiers comme professeur adjoint des Lycées et Collèges.', 'Selon ton classement : 13 places boursières (gratuité + allocation de l''État). Au-delà de ces quotas, l''inscription se fait à titre entièrement payant, selon le tarif fixé par l''établissement.', 'De bonnes bases en Culture générale et SVT(D)/PCT(D), doublées d''une bonne dose de pratique : stages, travaux dirigés et projets concrets tout au long de la formation « Production Animale ».', 'Au programme : Culture générale et SVT(D)/PCT(D), ainsi que les enseignements transversaux propres à une licence (méthodologie, langues, stages...).', 13, 0, 'Concours', '["C","D","DEAT/PA"]'::jsonb, '["Culture générale","SVT(D)/PCT(D)"]'::jsonb, '[]'::jsonb)
