INSERT INTO filieres (slug, ecole_id, nom, description, duree_etudes, niveau_entree, conditions_admission, debouches, cout_annuel_info, competences_visees, programme_resume, bourse, aide_fpp, mode_entree, bac_recommande, matieres, careers)
VALUES ('genie-electrique-et-informatique-informatique-et-telecommunications', (SELECT id FROM ecoles WHERE slug = 'institut-national-superieur-de-technologie-industrielle-insti'), 'Génie Electrique et Informatique (Informatique et Télécommunications)', 'Envie de te lancer dans « Génie Electrique et Informatique (Informatique et Télécommunications) » ? C''est une formation de premier cycle (licence) donnée par INSTI (Institut National Supérieur de Technologie Industrielle), qui mise en t''appuyant surtout sur Maths, Anglais(C et D)/Construction Mécanique(E)/Electrotech(F3) et qui débouche notamment sur des métiers comme service informatique d''entreprise - Cabinets d''audit ou ingénierie informatique - Agences de maintenance informatique - Agences de communication - Sociétés de développement d''applications web et mobiles - Fournisseurs d''accès internet - Télésurveillance - Systèmes embarqués.', '3 ans (Licence)', 'Baccalauréat C, D, E, F3, DT/Electrotech ou DT/Electrotech Appliquée', 'L''entrée se fait par le classement national du bac (ta moyenne au bac, calculée avec les coefficients de ta série, détermine ton rang). Cette année, 24 places boursières sont ouvertes sur cette filière ; au-delà, l''inscription se fait à titre payant.', 'Côté débouchés, cette filière mène vers des métiers comme service informatique d''entreprise - Cabinets d''audit ou ingénierie informatique - Agences de maintenance informatique - Agences de communication - Sociétés de développement d''applications web et mobiles - Fournisseurs d''accès internet - Télésurveillance - Systèmes embarqués.', 'Selon ton classement : 24 places boursières (gratuité + allocation de l''État). Au-delà de ces quotas, l''inscription se fait à titre entièrement payant, selon le tarif fixé par l''établissement.', 'De bonnes bases en Maths, Anglais(C, D)/Construction Mécanique(E)/Electrotech(F3) et SPCT, doublées d''une bonne dose de pratique : stages, travaux dirigés et projets concrets tout au long de la formation « Génie Electrique et Informatique (Informatique et Télécommunications) ».', 'Au programme : Maths, Anglais(C, D)/Construction Mécanique(E)/Electrotech(F3) et SPCT, ainsi que les enseignements transversaux propres à une licence (méthodologie, langues, stages...).', 24, 0, 'Classement', '["C","D","E","F3","DT/Electrotech","DT/Electrotech Appliquée"]'::jsonb, '["Maths","Anglais(C","D)/Construction Mécanique(E)/Electrotech(F3)","SPCT"]'::jsonb, '[]'::jsonb)
