INSERT INTO filieres (slug, ecole_id, nom, description, duree_etudes, niveau_entree, conditions_admission, debouches, cout_annuel_info, competences_visees, programme_resume, bourse, aide_fpp, mode_entree, bac_recommande, matieres, careers)
VALUES ('equipements-motorises', (SELECT id FROM ecoles WHERE slug = 'ecole-nationale-superieure-de-genie-energetique-et-procedes-ensgep'), 'Equipements motorisés', '« Equipements motorisés », c''est la filière de ENSGEP (École Nationale Supérieure de Génie Energétique et Procédés) pour celles et ceux qui veulent progresser en s''appuyant surtout sur Maths, Anglais/Français et SPCT(C, avec des débouchés concrets comme technicien supérieur en Installation et maintenance des matériels.', '3 ans (Licence)', 'Baccalauréat C, D, E, DT/MA ou DT/FM', 'L''entrée se fait par le classement national du bac (ta moyenne au bac, calculée avec les coefficients de ta série, détermine ton rang). Cette année, 24 places boursières sont ouvertes sur cette filière ; au-delà, l''inscription se fait à titre payant.', 'Une fois diplômé(e), tu peux viser des postes ou des activités comme technicien supérieur en Installation et maintenance des matériels, electromécanicien, installation et maintenance de matériels hydrauliques et pneumatiques ou maintenance des systèmes hydrauliques et pneumatiques.', 'Selon ton classement : 24 places boursières (gratuité + allocation de l''État). Au-delà de ces quotas, l''inscription se fait à titre entièrement payant, selon le tarif fixé par l''établissement.', 'De bonnes bases en Maths, Anglais/Français, SPCT(C et D)/Mécanique(E)/Construction Mécanique(DT/MA, doublées d''une bonne dose de pratique : stages, travaux dirigés et projets concrets tout au long de la formation « Equipements motorisés ».', 'Au programme : Maths, Anglais/Français, SPCT(C, D)/Mécanique(E)/Construction Mécanique(DT/MA et DT/FM), ainsi que les enseignements transversaux propres à une licence (méthodologie, langues, stages...).', 24, 0, 'Classement', '["C","D","E","DT/MA","DT/FM"]'::jsonb, '["Maths","Anglais/Français","SPCT(C","D)/Mécanique(E)/Construction Mécanique(DT/MA","DT/FM)"]'::jsonb, '[]'::jsonb)
