INSERT INTO filieres (slug, ecole_id, nom, description, duree_etudes, niveau_entree, conditions_admission, debouches, cout_annuel_info, competences_visees, programme_resume, bourse, aide_fpp, mode_entree, bac_recommande, matieres, careers)
VALUES ('genie-civil-4', (SELECT id FROM ecoles WHERE slug = 'ecole-nationale-superieure-de-genie-energetique-et-procedes-ensgep'), 'Génie Civil', '« Génie Civil », c''est la filière de ENSGEP (École Nationale Supérieure de Génie Energétique et Procédés) pour celles et ceux qui veulent progresser en s''appuyant surtout sur Maths, Anglais/Français et SPCT(E, avec des débouchés concrets comme assistants dans les bureaux d''études.', '3 ans (Licence)', 'Baccalauréat C, D, E, EA, F4 ou DT/BTP', 'L''entrée se fait par le classement national du bac (ta moyenne au bac, calculée avec les coefficients de ta série, détermine ton rang). Cette année, 21 places boursières sont ouvertes sur cette filière ; au-delà, l''inscription se fait à titre payant.', 'Une fois diplômé(e), tu peux viser des postes ou des activités comme assistants dans les bureaux d''études, techniciens contrôleurs de travaux du Génie Civil (routes, bâtiments, ouvrages d''art, assainissement) et de Mairies, techniciens dans les laboratoires hydrauliques et géotechniques, assistants des Experts Routiers, géotechniciens, entrepreneur, chef de chantier ou conducteur de travaux.', 'Selon ton classement : 21 places boursières (gratuité + allocation de l''État). Au-delà de ces quotas, l''inscription se fait à titre entièrement payant, selon le tarif fixé par l''établissement.', 'De bonnes bases en Maths, Anglais/Français, SPCT(E et D, doublées d''une bonne dose de pratique : stages, travaux dirigés et projets concrets tout au long de la formation « Génie Civil ».', 'Au programme : Maths, Anglais/Français, SPCT(E, D, E4)/RDM(F4 et DT/BTP)/Assainissement(EA), ainsi que les enseignements transversaux propres à une licence (méthodologie, langues, stages...).', 21, 0, 'Classement', '["C","D","E","EA","F4","DT/BTP"]'::jsonb, '["Maths","Anglais/Français","SPCT(E","D","E4)/RDM(F4","DT/BTP)/Assainissement(EA)"]'::jsonb, '[]'::jsonb)
