INSERT INTO filieres (slug, ecole_id, nom, description, duree_etudes, niveau_entree, conditions_admission, debouches, cout_annuel_info, competences_visees, programme_resume, bourse, aide_fpp, mode_entree, bac_recommande, matieres, careers)
VALUES ('architecture-et-urbanisme', (SELECT id FROM ecoles WHERE slug = 'ecole-nationale-superieure-des-travaux-publics-enstp'), 'Architecture et Urbanisme', 'Envie de te lancer dans « Architecture et Urbanisme » ? C''est une formation de premier cycle (licence) donnée par ENSTP (École Nationale Supérieure des Travaux Publics), qui mise en t''appuyant surtout sur Maths, Anglais/Français(F4) et SPCT(C et qui débouche notamment sur des métiers comme techniciens Architectes-Urbanistes.', '3 ans (Licence)', 'Baccalauréat C, D, F4, DT/OG ou DT/BTP', 'L''entrée se fait par le classement national du bac (ta moyenne au bac, calculée avec les coefficients de ta série, détermine ton rang). Cette année, 26 places boursières sont ouvertes sur cette filière ; au-delà, l''inscription se fait à titre payant.', 'Après cette formation, plusieurs portes s''ouvrent : tu peux te tourner vers techniciens Architectes-Urbanistes, techniciens Contrôleurs de chantiers de bâtiments, techniciens Contrôleurs des travaux d''aménagements urbains, assistants des experts aménagistes, assistants dans les Cabinets d''Architecture, agences immobilières et notaires ou assistants dans les services décentrés et Mairies.', 'Selon ton classement : 26 places boursières (gratuité + allocation de l''État). Au-delà de ces quotas, l''inscription se fait à titre entièrement payant, selon le tarif fixé par l''établissement.', 'De bonnes bases en Maths, Anglais/Français(F4), SPCT(C et D)/RDM(F4), doublées d''une bonne dose de pratique : stages, travaux dirigés et projets concrets tout au long de la formation « Architecture et Urbanisme ».', 'Au programme : Maths, Anglais/Français(F4), SPCT(C, D)/RDM(F4) et Technologie(DT/BTP)/DT/OG, ainsi que les enseignements transversaux propres à une licence (méthodologie, langues, stages...).', 26, 0, 'Classement', '["C","D","F4","DT/OG","DT/BTP"]'::jsonb, '["Maths","Anglais/Français(F4)","SPCT(C","D)/RDM(F4)","Technologie(DT/BTP)/DT/OG"]'::jsonb, '[]'::jsonb)
