INSERT INTO filieres (slug, ecole_id, nom, description, duree_etudes, niveau_entree, conditions_admission, debouches, cout_annuel_info, competences_visees, programme_resume, bourse, aide_fpp, mode_entree, bac_recommande, matieres, careers)
VALUES ('aquaculture', (SELECT id FROM ecoles WHERE slug = 'ecole-daquaculture-eaq'), 'Aquaculture', 'Envie de te lancer dans « Aquaculture » ? C''est une formation de premier cycle (licence) donnée par EAq (École d''Aquaculture), qui mise en t''appuyant surtout sur SVT, Maths et PCT et qui débouche notamment sur des métiers comme chargé des entreprises aquacoles.', '3 ans (Licence)', 'Baccalauréat C, D, DEAT/Pêche, aquaculture ou DEAT/Production animale', 'L''entrée se fait par le classement national du bac (ta moyenne au bac, calculée avec les coefficients de ta série, détermine ton rang). Cette année, 31 places boursières sont ouvertes sur cette filière ; au-delà, l''inscription se fait à titre payant.', 'Une fois diplômé(e), tu peux viser des postes ou des activités comme chargé des entreprises aquacoles, technicien en production de poissons, crabes, huîtres et de moules, technicien en conception et fabrication des aliments pour les espèces aquacoles d''élevage, technicien en conception, fabrication et entretien semences aquacoles ou conseiller/Assistant en aquaculture.', 'Selon ton classement : 31 places boursières (gratuité + allocation de l''État). Au-delà de ces quotas, l''inscription se fait à titre entièrement payant, selon le tarif fixé par l''établissement.', 'De bonnes bases en SVT, Maths, PCT et DEAT: 3 matières écrites, doublées d''une bonne dose de pratique : stages, travaux dirigés et projets concrets tout au long de la formation « Aquaculture ».', 'Au programme : SVT, Maths, PCT et DEAT: 3 matières écrites, ainsi que les enseignements transversaux propres à une licence (méthodologie, langues, stages...).', 31, 0, 'Classement', '["C","D","DEAT/Pêche","aquaculture","DEAT/Production animale"]'::jsonb, '["SVT","Maths","PCT","DEAT: 3 matières écrites"]'::jsonb, '[]'::jsonb)
