INSERT INTO filieres (slug, ecole_id, nom, description, duree_etudes, niveau_entree, conditions_admission, debouches, cout_annuel_info, competences_visees, programme_resume, bourse, aide_fpp, mode_entree, bac_recommande, matieres, careers)
VALUES ('industrie-des-produits-agro-alimentaires-et-nutrition-humaine-ipa-nh', (SELECT id FROM ecoles WHERE slug = 'ecole-des-sciences-et-techniques-de-conservation-et-transformation-des-produits-'), 'Industrie des Produits Agro-Alimentaires et Nutrition Humaine (IPA-NH)', '« Industrie des Produits Agro-Alimentaires et Nutrition Humaine (IPA-NH) », c''est la filière de ESTCTPA (École des Sciences et Techniques de Conservation et Transformation des Produits Agricoles) pour celles et ceux qui veulent progresser en s''appuyant surtout sur SVT, Maths et SPCT, avec des débouchés concrets comme technicien supérieur en industrie des produits agricoles carnés, céréaliers, de viande et poissons et produits halieutiques, fruits et légumes, etc.', '3 ans (Licence)', 'Baccalauréat C, D, DEAT/Nutrition ou Technologie Alimentaire', 'L''entrée se fait par le classement national du bac (ta moyenne au bac, calculée avec les coefficients de ta série, détermine ton rang). Cette année, 23 places boursières sont ouvertes sur cette filière ; au-delà, l''inscription se fait à titre payant.', 'Après cette formation, plusieurs portes s''ouvrent : tu peux te tourner vers technicien supérieur en industrie des produits agricoles carnés, céréaliers, de viande et poissons et produits halieutiques, fruits et légumes, etc, producteur et conservateur de produits agroalimentaires, contrôleur de la qualité des produits agricoles et normes agroalimentaires, conseiller/Assistant en transformation des produits agricoles, technicien en éducation nutritionnelle (ONG, entreprises, associations, autres), technicien des projets de nutrition ou enseignant dans les lycées techniques agricoles.', 'Selon ton classement : 23 places boursières (gratuité + allocation de l''État). Au-delà de ces quotas, l''inscription se fait à titre entièrement payant, selon le tarif fixé par l''établissement.', 'De bonnes bases en SVT, Maths, SPCT et DEAT: 3 matières écrites, doublées d''une bonne dose de pratique : stages, travaux dirigés et projets concrets tout au long de la formation « Industrie des Produits Agro-Alimentaires et Nutrition Humaine (IPA-NH) ».', 'Au programme : SVT, Maths, SPCT et DEAT: 3 matières écrites, ainsi que les enseignements transversaux propres à une licence (méthodologie, langues, stages...).', 23, 0, 'Classement', '["C","D","DEAT/Nutrition","Technologie Alimentaire"]'::jsonb, '["SVT","Maths","SPCT","DEAT: 3 matières écrites"]'::jsonb, '[]'::jsonb)
