INSERT INTO filieres (slug, ecole_id, nom, description, duree_etudes, niveau_entree, conditions_admission, debouches, cout_annuel_info, competences_visees, programme_resume, bourse, aide_fpp, mode_entree, bac_recommande, matieres, careers)
VALUES ('agroequipement', (SELECT id FROM ecoles WHERE slug = 'ecole-de-genie-rural-egr'), 'Agroéquipement', 'La licence « Agroéquipement », proposée par EGR (École de Génie Rural), te forme en t''appuyant surtout sur Maths, SPCT et Anglais, avec en ligne de mire des métiers comme entreprise de conception et de fabrication des machines agricoles. Trois ans après le bac, tu es prêt(e) à passer à l''action.', '3 ans (Licence)', 'Baccalauréat C, D, E, F1, F2, F3, DT/FM, DT/CEMS, DT/MA ou DEAT/AER', 'L''entrée se fait par le classement national du bac (ta moyenne au bac, calculée avec les coefficients de ta série, détermine ton rang). Cette année, 16 places boursières sont ouvertes sur cette filière ; au-delà, l''inscription se fait à titre payant.', 'Une fois diplômé(e), tu peux viser des postes ou des activités comme entreprise de conception et de fabrication des machines agricoles, société de maintenance des engins et équipements agricoles, entrepreneur de motoriste, entreprise d''installation et de maintenance d''équipements de production agroindustriels, entreprises et Fermes mécanisées agricoles, sociétés de maintenance de Tracteurs et de machines agricoles (usine d''agréage, Brasseries, Huileries, etc.), cabinets d''audit et de Conseils agricoles, etablissements d''enseignement technique ou administration publique.', 'Selon ton classement : 16 places boursières (gratuité + allocation de l''État). Au-delà de ces quotas, l''inscription se fait à titre entièrement payant, selon le tarif fixé par l''établissement.', 'De bonnes bases en Maths, SPCT, Anglais et F1, doublées d''une bonne dose de pratique : stages, travaux dirigés et projets concrets tout au long de la formation « Agroéquipement ».', 'Au programme : Maths, SPCT, Anglais, F1, F2, F3: Construction mécanique, DT/Electrotech ou EST/Electrotech(F2): Mécanique, DEAT: 3 matières écrites, pour E et pour DT/MA, ainsi que les enseignements transversaux propres à une licence (méthodologie, langues, stages...).', 16, 0, 'Classement', '["C","D","E","F1","F2","F3","DT/FM","DT/CEMS","DT/MA","DEAT/AER"]'::jsonb, '["Maths","SPCT","Anglais","pour E","F1","F2","F3: Construction mécanique","pour DT/MA","DT/Electrotech ou EST/Electrotech(F2): Mécanique","DEAT: 3 matières écrites"]'::jsonb, '[]'::jsonb)
