INSERT INTO filieres (slug, ecole_id, nom, description, duree_etudes, niveau_entree, conditions_admission, debouches, cout_annuel_info, competences_visees, programme_resume, bourse, aide_fpp, mode_entree, bac_recommande, matieres, careers)
VALUES ('electrification-rurale-et-energies-renouvelables-erer', (SELECT id FROM ecoles WHERE slug = 'ecole-de-genie-rural-egr'), 'Electrification Rurale et Energies Renouvelables (ERER)', 'Envie de te lancer dans « Electrification Rurale et Energies Renouvelables (ERER) » ? C''est une formation de premier cycle (licence) donnée par EGR (École de Génie Rural), qui mise en t''appuyant surtout sur Maths, SPCT et Français et qui débouche notamment sur des métiers comme industries de transformation et Unités de Production (agroalimentaire, cimenterie, production de sucre, lait, brasserie, coton, huile de palme, etc. utilisant du biogaz ou autres énergies renouvelables).', '3 ans (Licence)', 'Baccalauréat C, D, E, F1, F2, F3, DT/Electrotech ou DT/EAp', 'L''entrée se fait par le classement national du bac (ta moyenne au bac, calculée avec les coefficients de ta série, détermine ton rang). Cette année, 17 places boursières sont ouvertes sur cette filière ; au-delà, l''inscription se fait à titre payant.', 'Une fois diplômé(e), tu peux viser des postes ou des activités comme industries de transformation et Unités de Production (agroalimentaire, cimenterie, production de sucre, lait, brasserie, coton, huile de palme, etc. utilisant du biogaz ou autres énergies renouvelables), garages automobiles, entreprises travaillant dans le secteur des énergies vertes, projets d''électrification rurale, fermes et entreprises agropastorales, etablissements d''enseignement technique ou entrepreneuriat sur les énergies vertes et le développement durable.', 'Selon ton classement : 17 places boursières (gratuité + allocation de l''État). Au-delà de ces quotas, l''inscription se fait à titre entièrement payant, selon le tarif fixé par l''établissement.', 'De bonnes bases en Maths, SPCT, Français et F3, doublées d''une bonne dose de pratique : stages, travaux dirigés et projets concrets tout au long de la formation « Electrification Rurale et Energies Renouvelables (ERER) ».', 'Au programme : Maths, SPCT, Français, F3, DT/Electrotech: Electrotechnique appliquée, Français, Etude Electronique, pour F2 et pour DT/EAp: Sciences Appliquées, ainsi que les enseignements transversaux propres à une licence (méthodologie, langues, stages...).', 17, 0, 'Classement', '["C","D","E","F1","F2","F3","DT/Electrotech","DT/EAp"]'::jsonb, '["Maths","SPCT","Français","pour F2","F3","DT/Electrotech: Electrotechnique appliquée","pour DT/EAp: Sciences Appliquées","Français","Etude Electronique"]'::jsonb, '[]'::jsonb)
