INSERT INTO filieres (slug, ecole_id, nom, description, duree_etudes, niveau_entree, conditions_admission, debouches, cout_annuel_info, competences_visees, programme_resume, bourse, aide_fpp, mode_entree, bac_recommande, matieres, careers)
VALUES ('sociologie-rurale-et-vulgarisation-agricole', (SELECT id FROM ecoles WHERE slug = 'ecole-de-sociologie-rurale-et-de-vulgarisation-agricole-esrva'), 'Sociologie rurale et Vulgarisation Agricole', 'Envie de te lancer dans « Sociologie rurale et Vulgarisation Agricole » ? C''est une formation de premier cycle (licence) donnée par ESRVA (École de Sociologie rurale et de Vulgarisation Agricole), qui mise en t''appuyant surtout sur Maths, SPCT et SVT et qui débouche notamment sur des métiers comme technicien supérieur des entreprises agricoles.', '3 ans (Licence)', 'Baccalauréat C, D ou DEAT/toutes options', 'L''entrée se fait par le classement national du bac (ta moyenne au bac, calculée avec les coefficients de ta série, détermine ton rang). Cette année, 43 places boursières sont ouvertes sur cette filière ; au-delà, l''inscription se fait à titre payant.', 'Une fois diplômé(e), tu peux viser des postes ou des activités comme technicien supérieur des entreprises agricoles, technicien supérieur en Vulgarisateur/conseil agricole, technicien de recherche dans les institutions de recherche nationales et internationales dans le domaine de la sociologie rurale et de la vulgarisation agricole, conseiller technique de cabinet de conseil agricole et vulgarisation, fonctionnaire d''Etat (ministères), technicien de recherche dans les affaires techniques et financières des banques, conseiller technique en gestion des organisations paysannes et syndicats paysans, techniciens calculateurs et gestion des parcs et aires protégées (problématiques des populations riveraines), conseiller technique en nutrition humaine, enseignants des établissements et lycées et chaines de valeur agricole ou fonctionnaire des organisations de développement international (PNUD, Banque Mondiale, SNV, USAID etc).', 'Selon ton classement : 43 places boursières (gratuité + allocation de l''État). Au-delà de ces quotas, l''inscription se fait à titre entièrement payant, selon le tarif fixé par l''établissement.', 'De bonnes bases en Maths, SPCT, SVT et DEAT: 3 matières écrites, doublées d''une bonne dose de pratique : stages, travaux dirigés et projets concrets tout au long de la formation « Sociologie rurale et Vulgarisation Agricole ».', 'Au programme : Maths, SPCT, SVT et DEAT: 3 matières écrites, ainsi que les enseignements transversaux propres à une licence (méthodologie, langues, stages...).', 43, 0, 'Classement', '["C","D","DEAT/toutes options"]'::jsonb, '["Maths","SPCT","SVT","DEAT: 3 matières écrites"]'::jsonb, '[]'::jsonb)
