INSERT INTO filieres (slug, ecole_id, nom, description, duree_etudes, niveau_entree, conditions_admission, debouches, cout_annuel_info, competences_visees, programme_resume, bourse, aide_fpp, mode_entree, bac_recommande, matieres, careers)
VALUES ('metiers-de-lagriculture', (SELECT id FROM ecoles WHERE slug = 'ecole-de-foresterie-tropicale-efort'), 'Métiers de l''agriculture', '« Métiers de l''agriculture », c''est la filière de EForT (École de Foresterie Tropicale) pour celles et ceux qui veulent progresser en s''appuyant surtout sur Culture générale, SVT et PCT, avec des débouchés concrets comme métiers de l''agriculture.', '3 ans (Licence)', 'Baccalauréat C, D ou DT/Agriculture générale(DEAT)', 'L''entrée se fait par un concours d''entrée. Cette année, 50 places boursières sont ouvertes sur cette filière ; au-delà, l''inscription se fait à titre payant.', 'Après cette formation, plusieurs portes s''ouvrent : tu peux te tourner vers métiers de l''agriculture.', 'Selon ton classement : 50 places boursières (gratuité + allocation de l''État). Au-delà de ces quotas, l''inscription se fait à titre entièrement payant, selon le tarif fixé par l''établissement.', 'De bonnes bases en Culture générale, SVT, PCT et Français, doublées d''une bonne dose de pratique : stages, travaux dirigés et projets concrets tout au long de la formation « Métiers de l''agriculture ».', 'Au programme : Culture générale, SVT, PCT, Français et DEAT: toutes options, ainsi que les enseignements transversaux propres à une licence (méthodologie, langues, stages...).', 50, 0, 'Concours', '["C","D","DT/Agriculture générale(DEAT)"]'::jsonb, '["Culture générale","SVT","PCT","Français","DEAT: toutes options"]'::jsonb, '[]'::jsonb)
